import XCTest
@testable import MRTDKit

final class CSCATests: XCTestCase {
    // Certificate chains generated with Python `cryptography`:
    // RSA-2048 CSCA → P-256 DSC (sha256WithRSA), brainpoolP384r1 CSCA → brainpoolP256r1 DSC (ecdsa-with-SHA384).
    static let rsaCSCA = ""
    static let rsaDSC = ""
    static let ecCSCA = ""
    static let ecDSC = ""

    func cert(_ hex: String) throws -> Certificate { try Certificate(der: Bytes(hex: hex)!) }

    func testChains() throws {
        for (ca, ds) in [(Self.rsaCSCA, Self.rsaDSC), (Self.ecCSCA, Self.ecDSC)] {
            let csca = try cert(ca), dsc = try cert(ds)
            XCTAssertTrue(csca.isCA)
            XCTAssertEqual(dsc.authorityKeyIdentifier, csca.subjectKeyIdentifier)
            XCTAssertEqual(dsc.isSigned(by: csca), .valid)
            XCTAssertEqual(csca.isSigned(by: csca), .valid) // self-signed

            let store = CSCAStore(certificates: [csca])
            XCTAssertEqual(store.verify(dsc: dsc).0, .valid)
            XCTAssertEqual(store.countries, ["UT"])
        }
    }

    func testWrongOrMissingCSCA() throws {
        let rsaDSC = try cert(Self.rsaDSC)
        XCTAssertNotEqual(CSCAStore(certificates: [try cert(Self.ecCSCA)]).verify(dsc: rsaDSC).0, .valid)
        if case .notChecked = CSCAStore().verify(dsc: rsaDSC).0 {} else { XCTFail() }

        // A DSC whose signature was tampered with must not verify.
        var bytes = Bytes(hex: Self.ecDSC)!
        bytes[bytes.count - 5] ^= 0x01
        let tampered = try Certificate(der: bytes)
        XCTAssertNotEqual(tampered.isSigned(by: try cert(Self.ecCSCA)), .valid)
    }

    func testMasterListAndFileFormats() throws {
        let ca1 = Bytes(hex: Self.rsaCSCA)!, ca2 = Bytes(hex: Self.ecCSCA)!
        // CMS SignedData with a CscaMasterList as content (as published by e.g. BSI).
        let list = TLV.encode(0x30, TLV.encode(0x02, [0]) + TLV.encode(0x31, ca1 + ca2))
        let encap = TLV.encode(0x30, TLV.encode(0x06, ASN1.encodeOID("2.23.136.1.1.2")) + TLV.encode(0xA0, TLV.encode(0x04, list)))
        let sd = TLV.encode(0x30, TLV.encode(0x02, [3]) + TLV.encode(0x31, []) + encap + TLV.encode(0x31, []))
        let ml = TLV.encode(0x30, TLV.encode(0x06, ASN1.encodeOID("1.2.840.113549.1.7.2")) + TLV.encode(0xA0, sd))
        XCTAssertEqual(CSCAStore.certificates(fromFile: ml).count, 2)

        let ldif = "version: 1\n\ndn: cn=x,dc=CSCAMasterList\npkdMasterListContent:: " + Data(ml).base64EncodedString().enumerated()
            .map { $0.offset > 0 && $0.offset % 76 == 0 ? "\n \($0.element)" : String($0.element) }.joined() + "\n"
        XCTAssertEqual(CSCAStore.certificates(fromFile: Bytes(ldif.utf8)).count, 2)

        let pem = "-----BEGIN CERTIFICATE-----\n\(Data(ca1).base64EncodedString(options: .lineLength64Characters))\n-----END CERTIFICATE-----\n"
        XCTAssertEqual(CSCAStore.certificates(fromFile: Bytes(pem.utf8)).count, 1)
        XCTAssertEqual(CSCAStore.certificates(fromFile: ca2).count, 1)

        let store = CSCAStore(certificates: CSCAStore.certificates(fromFile: ml))
        XCTAssertEqual(store.add(CSCAStore.certificates(fromFile: ca2)), 0) // duplicate
        let url = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
        try store.save(to: url)
        XCTAssertEqual(CSCAStore.load(from: url).certificates.count, 2)
        try? FileManager.default.removeItem(at: url)
    }
}
